export function normalize(text){return String(text??'').normalize('NFKD').replace(/[\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g,'').replace(/[أإآٱ]/g,'ا').replace(/[يى]/g,'ی').replace(/ك/g,'ک').replace(/ة/g,'ه').replace(/[\u200c\u200d]/g,' ').replace(/\s+/g,' ').trim().toLowerCase();}
export function matches(text,query){const terms=normalize(query).split(' ').filter(Boolean);const hay=normalize(text);return terms.every(t=>hay.includes(t));}
export function validateBackup(data){if(!data||data.format!=='mansour-research-v1'||!Array.isArray(data.notes)||!Array.isArray(data.bookmarks))throw Error('فرمت پشتیبان معتبر نیست');if(data.notes.length>20000||data.bookmarks.length>6236)throw Error('حجم پشتیبان بیش از حد مجاز است');for(const n of data.notes){if(!Number.isInteger(n.ayahId)||n.ayahId<1||n.ayahId>6236||typeof n.text!=='string'||n.text.length>100000||typeof n.id!=='string')throw Error('یادداشت نامعتبر است');}for(const id of data.bookmarks)if(!Number.isInteger(id)||id<1||id>6236)throw Error('نشان نامعتبر است');return data;}
export function mergeBackup(current,incoming){validateBackup(incoming);const notes=new Map(current.notes.map(n=>[n.id,n]));for(const n of incoming.notes)notes.set(n.id,n);return{format:'mansour-research-v1',notes:[...notes.values()],bookmarks:[...new Set([...current.bookmarks,...incoming.bookmarks])]};}
